# US-4127 — Update order status from the order detail page

## User story

As a customer support agent, I want to set an order's status to "Shipped" from the order detail page, so that I stop emailing the logistics team for every update.

## Business context

Support handles roughly 400 status updates per week over email. Each hand-off takes 20–40 minutes and sometimes gets lost between inboxes. Letting agents update the status directly should remove most of that manual work and cut the delay between dispatch and the customer seeing "Shipped" from hours to minutes.

## Acceptance criteria

- An agent with the Support role can change an order's status to Shipped from the order detail page.
- The change records the timestamp of the status update.
- The endpoint rejects requests from users without the Support role.

Code diff the description refers to:

diff --git a/src/Api/Controllers/OrdersController.cs b/src/Api/Controllers/OrdersController.cs
index 4a1c9f2..b7e3d10 100644
--- a/src/Api/Controllers/OrdersController.cs
+++ b/src/Api/Controllers/OrdersController.cs
@@ -28,6 +28,17 @@ public sealed class OrdersController : ControllerBase
         return Ok(order);
     }

+    [HttpPatch("{id:int}/status")]
+    [Authorize(Roles = "Support")]
+    public async Task<IActionResult> UpdateStatus(int id, [FromBody] UpdateOrderStatusRequest request)
+    {
+        var updated = await _orderService.UpdateStatusAsync(id, request.Status, HttpContext.RequestAborted);
+        return updated ? NoContent() : NotFound();
+    }
+
     [HttpDelete("{id:int}")]
     [Authorize(Roles = "Admin")]
     public async Task<IActionResult> Delete(int id)
diff --git a/src/Api/Dtos/UpdateOrderStatusRequest.cs b/src/Api/Dtos/UpdateOrderStatusRequest.cs
new file mode 100644
index 0000000..e69de29
--- /dev/null
+++ b/src/Api/Dtos/UpdateOrderStatusRequest.cs
@@ -0,0 +1,8 @@
+using System.ComponentModel.DataAnnotations;
+
+namespace Shop.Api.Dtos;
+
+public sealed record UpdateOrderStatusRequest(
+    [Required, RegularExpression("^(Pending|Shipped|Delivered|Cancelled)$")]
+    string Status);
diff --git a/src/Application/Orders/OrderService.cs b/src/Application/Orders/OrderService.cs
index 91b2aa4..c4d5e77 100644
--- a/src/Application/Orders/OrderService.cs
+++ b/src/Application/Orders/OrderService.cs
@@ -64,6 +64,19 @@ public sealed class OrderService : IOrderService
         return order;
     }

+    public async Task<bool> UpdateStatusAsync(int orderId, string status, CancellationToken ct)
+    {
+        var order = await _repository.FindByIdAsync(orderId, ct);
+        if (order is null)
+        {
+            return false;
+        }
+
+        order.Status = status;
+        order.StatusUpdatedAt = DateTime.UtcNow;
+        await _repository.SaveChangesAsync(ct);
+        return true;
+    }
+
     public async Task DeleteAsync(int orderId, CancellationToken ct)
diff --git a/src/Infrastructure/Migrations/Scripts/20261101_add_status_updated_at.sql b/src/Infrastructure/Migrations/Scripts/20261101_add_status_updated_at.sql
