--- /dev/null
+++ b/src/Infrastructure/Migrations/Scripts/20261101_add_status_updated_at.sql
@@ -0,0 +1,3 @@
+-- src/Infrastructure/Migrations/Scripts/20261101_add_status_updated_at.sql
+ALTER TABLE Orders ADD StatusUpdatedAt datetime2 NULL;
+GO
diff --git a/tests/Orders/OrdersControllerTests.cs b/tests/Orders/OrdersControllerTests.cs
index 77c1e2b..2f9a8d4 100644
--- a/tests/Orders/OrdersControllerTests.cs
+++ b/tests/Orders/OrdersControllerTests.cs
@@ -41,4 +41,18 @@ public sealed class OrdersControllerTests
         Assert.IsType<OkObjectResult>(result);
     }
+
+    [Fact]
+    public async Task UpdateStatus_ReturnsNoContent_WhenOrderExists()
+    {
+        var service = new Mock<IOrderService>();
+        service.Setup(s => s.UpdateStatusAsync(7, "Shipped", It.IsAny<CancellationToken>()))
+               .ReturnsAsync(true);
+        var controller = new OrdersController(service.Object);
+
+        var result = await controller.UpdateStatus(7, new UpdateOrderStatusRequest("Shipped"));
+
+        Assert.IsType<NoContentResult>(result);
+        service.Verify(s => s.UpdateStatusAsync(7, "Shipped", It.IsAny<CancellationToken>()), Times.Once);
+    }
 }

PR description to grade:

### What is this change?

Adds a `PATCH /orders/{id}/status` endpoint that lets Support agents set an order's status to `Shipped` from the order detail page, recording the update timestamp.

### Type of change?

- New feature (non-breaking change which adds functionality)

### Why?

Support currently handles ~400 order status updates per week over email, with each hand-off taking 20–40 minutes and sometimes getting lost between inboxes. Letting agents update the status directly removes most of that manual work and reduces the delay between dispatch and the customer seeing "Shipped" from hours to minutes.

### How?

- Added `UpdateStatus` action to `OrdersController` with `HttpPatch("{id:int}/status")` and `[Authorize(Roles = "Support")]`, returning `204 NoContent` or `404 NotFound`.
- Added `UpdateOrderStatusRequest` DTO with a `Required` `Status` field constrained by a `RegularExpression` to `Pending|Shipped|Delivered|Cancelled`.
- Added `OrderService.UpdateStatusAsync` to load the order, set `Status`, set `StatusUpdatedAt` to `DateTime.UtcNow`, and save changes.
- Added migration SQL to add `StatusUpdatedAt` column to the `Orders` table.
- Added `UpdateStatus_ReturnsNoContent_WhenOrderExists` controller test.

### Requires Manual Database Migration?

Yes.

```sql
ALTER TABLE Orders ADD StatusUpdatedAt datetime2 NULL;
GO
```

### Anything Else?

The DTO allows `Pending`, `Delivered`, and `Cancelled` in addition to `Shipped`, but the user story only requires `Shipped`. The `StatusUpdatedAt` column is nullable, so existing orders remain compatible. The endpoint is restricted to the `Support` role as required.

Rubric criterion:

The "Why?" field explains the business reason stated in the User Story (support handling ~400 manual status updates per week, 20-40 minute hand-offs, hours-to-minutes delay), not a restatement of the code change.


